--- export-coverage.before.cjs
+++ export-coverage.cjs
@@ -1,7 +1,7 @@
 const fs = require('node:fs'), path = require('node:path'), crypto = require('node:crypto'), assert = require('node:assert/strict');
 const [directory, root, output] = process.argv.slice(2), hash = s => crypto.createHash('sha256').update(s).digest('hex');
 const normalize = s => s.replaceAll('\r\n', '\n');
-const files = new Map(), tests = new Map(), exclusions = [], sourceHashes = {};
+const files = new Map(), tests = new Map(), exclusions = [], sourceHashes = {}, terminalEofExclusions = new Map();
 for (const name of fs.readdirSync(directory).filter(name => name.endsWith('.json'))) {
     const capture = JSON.parse(fs.readFileSync(path.join(directory, name), 'utf8'));
     exclusions.push(...capture.excluded.map(row => ({test:capture.test, ...row})));
@@ -16,11 +16,18 @@
         const locations = JSON.parse(fs.readFileSync(path.join(directory, 'sources', record.source_hash+'.locations.json'), 'utf8'));
         const denominator = [...new Set(locations.map(point => point.lineNumber+1))].sort((a,b) => a-b);
         assert.deepEqual(record.executableLines.slice().sort((a,b) => a-b), denominator, 'Native executable lines');
+        const sourceLines = source.split('\n'), finalLine = sourceLines.length-1;
+        const executable = new Set(locations.filter(point => {
+            const terminal = sourceLines[finalLine] === '' && point.type === 'return' && point.lineNumber === finalLine && point.columnNumber === 0;
+            if (terminal) terminalEofExclusions.set(record.source_hash, {file:record.file, source_hash:record.source_hash, line:finalLine+1, column:0, type:'return'});
+            return !terminal;
+        }).map(point => point.lineNumber+1));
+        for (const line of record.coveredLines) assert(executable.has(line), 'Covered line must remain in the effective native denominator');
         const context = test+'\0'+record.file;
         if (!tests.has(context)) tests.set(context, {test, file:record.file, executable:new Set(), covered:new Set()});
         if (!files.has(record.file)) files.set(record.file, {executable:new Set(), covered:new Set()});
         for (const result of [tests.get(context), files.get(record.file)]) {
-            for (const line of record.executableLines) result.executable.add(line);
+            for (const line of executable) result.executable.add(line);
             for (const line of record.coveredLines) { assert(result.executable.has(line)); result.covered.add(line); }
         }
     }
@@ -34,9 +41,10 @@
     lcov.push('LF:'+executable.size, 'LH:'+covered.size, 'end_of_record');
 }
 const summary = {created:new Date().toISOString(), root, sourceHashes, tests:[...new Set([...tests.values()].map(row=>row.test))], exclusions,
-    method:'Fresh native Edge V8 precise ranges mapped to native possible-breakpoint lines. Exact source hashes verified after CRLF normalization. Per-suite contexts and hit-wins line union; no branch coverage. Frozen reference contexts, source mutations and VM snippets are excluded.',
+    method:'Fresh native Edge V8 precise ranges mapped to native possible-breakpoint lines. Exact source hashes verified after CRLF normalization. Full raw native line sets are validated; only return points at column 0 of the final empty EOF line are excluded from effective executable-line totals. Per-suite contexts and hit-wins line union; no branch coverage. Frozen reference contexts, source mutations and VM snippets are excluded.',
+    terminalEofExclusionSources:terminalEofExclusions.size, terminalEofExclusions:[...terminalEofExclusions.values()],
     files:Object.fromEntries([...files].map(([name, row])=>[name,{covered:row.covered.size, executable:row.executable.size, percent:100*row.covered.size/row.executable.size, uncovered:[...row.executable].filter(line=>!row.covered.has(line)).sort((a,b)=>a-b)}]))};
 const totals = Object.values(summary.files).reduce((sum,row)=>({covered:sum.covered+row.covered, executable:sum.executable+row.executable}),{covered:0,executable:0});
 summary.totals = {...totals, percent:100*totals.covered/totals.executable};
 fs.writeFileSync(output, lcov.join('\n')+'\n'); fs.writeFileSync(output+'.summary.json', JSON.stringify(summary,null,2)+'\n');
-console.log(JSON.stringify({tests:summary.tests.length, files:Object.fromEntries(Object.entries(summary.files).map(([name,{covered,executable,percent}])=>[name,{covered,executable,percent}])), totals:summary.totals, exclusions:exclusions.length}));
+console.log(JSON.stringify({tests:summary.tests.length, files:Object.fromEntries(Object.entries(summary.files).map(([name,{covered,executable,percent}])=>[name,{covered,executable,percent}])), totals:summary.totals, exclusions:exclusions.length, terminalEofExclusionSources:terminalEofExclusions.size}));
